local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
local KTool = CS.Engine.Lib.KTool
local SDKService = import('Game.Entry.SDKService')
---@type ActivityUtils
local ActivityUtils  = import("Game.Activity.ActivityUtils")
local cs_coroutine      = require 'XLua.cs_coroutine'
local Yielders = CS.Engine.Lib.Yielders

--- from: Assets/BundleResources/Prefabs/Activity/ShareActivityBackPanel.prefab
---@class UIActivitySharePanel
---@field Env                           	UIActivitySharePanel
---@field controller                    	Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field TxtUid                        	TMPro.TextMeshProUGUI
---@field ImgTitle                      	UnityEngine.UI.RawImage
---@field TxtNumber                     	TMPro.TextMeshProUGUI
---@field TxtContent                    	UnityEngine.UI.Text
---@field TxtName                       	UnityEngine.UI.Text
---@field Bg                            	UnityEngine.UI.RawImage


local UIActivitySharePanel = Class("UIActivitySharePanel")

function UIActivitySharePanel:__init()
end

function UIActivitySharePanel:__delete()
    self.controller = nil
end

function UIActivitySharePanel:Awake()
    local isOpenFtCommunity = SDKService:GetInstance():IsOfficialSDK()
    local codeGroup = self.controller.gameObject.transform:Find("Root/Container/MiddlePanel/CodeGroup")
    KTool.SetActive(codeGroup, (isOpenFtCommunity or GameUtils.IsWindow()) and (not IS_REVIEW) )
end

function UIActivitySharePanel:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
end

---@param data {sceneId : str, code : str, desc : str, title : str}
function UIActivitySharePanel:OnInit(data)
    cs_coroutine.start(function()
        local loadImgNum = 2
        CfUtils.FillText(self.TxtName, string.format(localize("昵称:%s"), playerComponent.playerDojo.playerName))
        CfUtils.FillText(self.TxtUid, string.format("UID:%s", playerComponent.playerDojo.playerId))
        if data.sceneId ~= "" then
            CfUtils.FillImage(self.Bg,  ActivityUtils.GetImageFullPath(data.sceneId), nil, nil, nil, nil, function()
                loadImgNum = loadImgNum - 1
            end)
        end
        CfUtils.FillText(self.TxtContent, tostring(data.desc))
        CfUtils.FillText(self.TxtNumber, tostring(data.code))
        CfUtils.FillImage(self.ImgTitle, ActivityUtils.GetImageFullPath(data.title), nil, nil, nil, nil, function()
            loadImgNum = loadImgNum - 1
        end)

        while loadImgNum > 0 do
            cs_coroutine.yield_return(Yielders.EndOfFrame)
        end
        if self.onCompleteCB then
            self.onCompleteCB()
        end
    end)
end

function UIActivitySharePanel:SetInitCompleteCB(cb)
    self.onCompleteCB = cb
end

return UIActivitySharePanel